INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("占いが得意な霊能少女", 12, "悪魔偽王国軍（ディアボロス）", 0, "シノブ（ハロウィン）", "AB", 42, 108101, 157, 7, 22, "占い", "大坪由佳", "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", "魔族", 18);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("プリン大好きゴースト娘", 1, "悪魔偽王国軍（ディアボロス）", 0, "ミヤコ（ハロウィン）", "B", 32, 108201, 130, 7, 23, "プリンを食べること", "雨宮天", "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～", "魔族", 14);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("ちょっとおませな恋に恋する女の子", 1, "ルーセント学院", 0, "ミサキ（ハロウィン）", "A", 22, 108301, 120, 14, 3, "ファッション誌鑑賞、コスメ集め", "久野美咲", "アタシのこと呼んだ？\nレディの魅力で夢中にさせてあげるわね！", "魔族", 11);
