INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("泣き虫で臆病な守ってあげたい女の子", 6, "サレンディア救護院", 0, "クルミ（クリスマス）", "B", 40, 108501, 150, 9, 9, "観劇、おままごと", "植田佳奈", "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！", "ヒューマン", 12);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("ぷうきちといつも一緒！", 5, "サレンディア救護院", 0, "アヤネ（クリスマス）", "B", 38, 108601, 148, 9, 10, "屋内でできる遊び", "芹澤優", "この子はね、ぷうきちって言うんだ\n武器なんだけど、しゃべるんだよ♪\n大事な大事な、私の友達なんだぁ～！", "ヒューマン", 14);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("人助けが大好き！　前向き格闘娘", 8, "トゥインクルウィッシュ", 0, "ヒヨリ（ニューイヤー）", "A", 44, 108701, 155, 2, 27, "人助け、応援", "東山奈央", "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", "獣人族", 16);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("戦闘のサポートが得意な、心優しい少女", 4, "トゥインクルウィッシュ", 0, "ユイ（ニューイヤー）", "O", 47, 108801, 158, 2, 5, "料理、人間観察", "種田梨沙", "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", "ヒューマン", 17);
